/* cppi::c16b06701d6023205657743ff1bde69445c7c0c24edeaa9a5e3e65f3c024e5e1 */
SELECT COUNT(*) FROM (WITH filtered_index AS (SELECT business_date, id_cppib_index, index_description, rimes_source_code, rimes_source_description, index_value_base, return_daily_base, inception_return_base, feed_version FROM market.cppib_index WHERE id_cppib_index IN ('G0O1_TR_CAD_0_0', 'G0O1_TR_USD_0_0') AND business_date BETWEEN DATE '2025-04-01' AND DATE '2025-04-30'), latest_feed_versions AS (SELECT id_cppib_index, business_date, MAX(feed_version) AS feed_version FROM filtered_index GROUP BY id_cppib_index, business_date) SELECT f.business_date, f.id_cppib_index, f.index_description, f.return_daily_base, f.inception_return_base FROM filtered_index f JOIN latest_feed_versions lfv ON f.id_cppib_index = lfv.id_cppib_index AND f.business_date = lfv.business_date AND f.feed_version = lfv.feed_version
) dbvrcnt

/* cppi::fb7aa12f1f11795fa3906515354aea7dfcb42ab68aefa779edd15ccac8135f10 */
select index_id, time_key, currency_code, geography, country_name, index_value, source_file
from (
        select *, max(last_publish) over (partition by index_id, time_key) max_publish
            from market.tfm_gdp_index
            where time_key between 1984 and 2030
            and last_publish <= date '2025-05-01'
    ) a
where last_publish = max_publish

